fn clip(a: Vec<i8>, min: i8, max: i8) -> Vec<i8> {
    // Pre-allocate a result vector of the same length as `a`.
    let mut result = Vec::with_capacity(a.len());

    for &x in &a {
        // Clip each element to the inclusive range [min, max].
        let y = if x < min {
            min
        } else if x > max {
            max
        } else {
            x
        };
        result.push(y);
    }

    result
}

